SourceCode.Declaration:
/// <summary>
/// CB167_PerformStockReservation.
/// Service class to reserve inventory transactions.
/// </summary>
class METInventTransReserveService
{
    InventTransId inventTransId;
    InventQty     lineQty;

    boolean pickPartialReservedLine;

}

Method.Source:
/// <summary>
/// Gets and sets inventTransId of line.
/// </summary>
/// <param name = "_inventTransId">inventTransId.</param>
/// <returns>inventTransId.</returns>
public InventTransId parmInventTransId(InventTransId _inventTransId = inventTransId)
{
    inventTransId = _inventTransId;
    return inventTransId;
}

/// <summary>
/// Gets and sets line qty.
/// </summary>
/// <param name = "_lineQty">Line qty.</param>
/// <returns>Line and qty.</returns>
public InventQty parmLineQty(InventQty _lineQty = lineQty)
{
    lineQty = _lineQty;
    return lineQty;
}

/// <summary>
/// Creates and initializes object of the service class.
/// </summary>
/// <param name = "_inventTransId">Inventory transaction id.<</param>
/// <param name = "_lineQty">Line qty.</param>
/// <returns>>Object of the service class.</returns>
public static METInventTransReserveService construct(InventTransId _inventTransId, InventQty _lineQty)
{
    METInventTransReserveService reserveService = new METInventTransReserveService();

    reserveService.parmInventTransId(_inventTransId);
    reserveService.parmLineQty(_lineQty);

    return reserveService;
}

public boolean parmPickPartialReservedLine(boolean _pickPartialReservedLine = pickPartialReservedLine)
{
    pickPartialReservedLine = _pickPartialReservedLine;
    return pickPartialReservedLine;
}

/// <summary>
///  Runs the reservation process.
/// </summary>
/// <param name = "_pickPartialReservedLine">
/// True, if partial reserved lines are to be picked for reservation; otherwise, false.
/// </param>
public void reserve()
{
    InventMovement        inventMovement;
    InventUpd_Reservation reservation;
    InventTransOrigin     inventTransOrigin;
    InventTrans           inventTrans;
    InventQty             reserveQty;

    select firstonly inventTrans
        where inventTrans.StatusIssue == StatusIssue::OnOrder
    exists join inventTransOrigin
        where inventTransOrigin.RecId == inventTrans.InventTransOrigin
        &&    inventTransOrigin.InventTransId == inventTransId;

    if (!inventTrans)
    {
        return;
    }

    reserveQty = abs(inventTrans.Qty);

    if (pickPartialReservedLine  || (lineQty && reserveQty == lineQty))
    {
        reserveQty     = abs(inventTrans.Qty);
        inventMovement = inventTrans.inventMovement(true);
        reservation    = InventUpd_Reservation::newMovement(inventMovement, -reserveQty, true);

        reservation.updateNow();
    }
}
